#!/usr/bin/env python3
"""Falsify a degree bound based on injectivity of the leading operator symbol."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3];R=ROOT/'research/benincasa/results'
# H=3X^2-6Y^2+54, K=H^2. Represent dK components factored.
# dKx=12 X H, dKy=-24 Y H. The vector (2Y,X) is a syzygy.
for x,y,h in [(1,2,5),(3,-1,7),(4,5,-2)]:assert (2*y)*(12*x*h)+x*(-24*y*h)==0
out={'schema':'marici.benincasa.cosmology-rees-operator-symbol-kernel.v1','problem':'derive a uniform polynomial-preimage degree bound from the leading symbol of the fixed operator matrix','bold_conjecture':'the degree-A+3 derivative symbol is injective, forcing all sufficiently high derivative inputs to vanish in a low-degree output','named_rivals':['injective leading symbol','Koszul symbol kernel generated by the gradient of K','lower-order compatibility that kills or propagates the symbol kernel'],'risky_consequences':['partial_X K and partial_Y K must have no polynomial syzygies relevant to the shared target coordinate','arbitrary-degree symbol cancellation must be absent'],'strongest_falsification_attempt':{'special_fiber_factorization':'K=H^2 with H=3X^2-6Y^2+54','gradient':['partial_X K=12 X H','partial_Y K=-24 Y H'],'symbol_syzygy':'(2Y)*(partial_X K)+X*(partial_Y K)=0','arbitrary_degree_family':'multiply (2Y,X) by any polynomial g','exact_residual':0},'disposition':'reject an injective-symbol degree bound; the principal symbol has an arbitrary-degree kernel','surviving_scope':'a degree bound may still follow after prolonging this kernel through lower-order derivative and dq terms','first_missing_object':'the induced lower-order operator on the symbol-kernel generator, i.e. its first Spencer/prolongation obstruction','acceptance_test':'substitute derivative inputs g(2Y,X) into the full operator, compute the reduced lower-degree residual modulo K/q multiplication images, and test whether its leading map is injective in g','passed':True};(R/'cosmology_rees_operator_symbol_kernel.json').write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2))
